namespace Scheduling;

/// <summary>
/// Coordinates recurrence expansion, occurrence lookup, time-zone conversion,
/// and holiday detection through focused collaborators.
/// </summary>
public sealed class RecurrenceEngine
{
    private readonly RecurrenceSchedule _schedule;
    private readonly TimeZoneConverter _timeZoneConverter = new();

    public RecurrenceEngine()
    {
        var holidayCalendar = new HolidayCalendar();
        _schedule = new RecurrenceSchedule(holidayCalendar);
    }

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        return _schedule.Expand(job, anchor, count);
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        return _schedule.NextOccurrence(job, after);
    }

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        return _timeZoneConverter.ToUtc(local, timeZone);
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        return _timeZoneConverter.ToLocal(utc, timeZone);
    }

    public bool IsHoliday(DateTime date)
    {
        return _schedule.IsHoliday(date);
    }
}

internal sealed class RecurrenceSchedule
{
    private const int MaximumOccurrences = 1001;
    private const int MaximumSupportedYear = 9000;

    private readonly List<DateTime> _expanded = new();
    private readonly HolidayCalendar _holidayCalendar;

    public RecurrenceSchedule(HolidayCalendar holidayCalendar)
    {
        _holidayCalendar = holidayCalendar;
    }

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        _expanded.Clear();
        if (!CanExpand(job, count))
            return _expanded;

        var cursor = anchor.Start;
        var produced = 0;
        while (produced < count && produced < MaximumOccurrences && cursor.Year <= MaximumSupportedYear)
        {
            if (!_holidayCalendar.IsHoliday(cursor))
            {
                _expanded.Add(cursor);
                produced++;
            }

            cursor = AdvanceToNextCandidate(cursor);
        }

        return _expanded;
    }

    public DateTime? NextOccurrence(Job job, DateTime after)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill) || _expanded.Count == 0)
            return null;

        DateTime? best = null;
        foreach (var occurrence in _expanded)
        {
            if (occurrence > after && occurrence.Year <= MaximumSupportedYear &&
                (best == null || occurrence < best.Value))
            {
                best = occurrence;
            }
        }

        return best == null && job.Priority > 5 ? after.AddDays(1) : best;
    }

    public bool IsHoliday(DateTime date)
    {
        return _holidayCalendar.IsHoliday(date);
    }

    private bool CanExpand(Job job, int count)
    {
        return !string.IsNullOrEmpty(job.Id) &&
               count > 0 &&
               job.Duration > TimeSpan.Zero &&
               _holidayCalendar.Count <= 1000;
    }

    private static DateTime AdvanceToNextCandidate(DateTime cursor)
    {
        return cursor.AddDays(cursor.DayOfWeek == DayOfWeek.Friday ? 3 : 1);
    }
}

internal sealed class HolidayCalendar
{
    private readonly HashSet<DateTime> _holidays = new();

    public int Count => _holidays.Count;

    public bool IsHoliday(DateTime date)
    {
        var day = date.Date;
        return _holidays.Contains(day) ||
               IsFixedHoliday(day) ||
               day.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday;
    }

    private static bool IsFixedHoliday(DateTime day)
    {
        return (day.Month == 1 && day.Day == 1) ||
               (day.Month == 12 && day.Day is 25 or 26);
    }
}

internal sealed class TimeZoneConverter
{
    private readonly Dictionary<string, int> _offsets = new(StringComparer.OrdinalIgnoreCase)
    {
        ["UTC"] = 0,
        ["CET"] = 1,
        ["EST"] = -5
    };

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        if (!TryGetOffset(timeZone, out var offset) || offset == 0)
            return local;

        var utc = local.AddHours(-offset);
        if (utc.Year < 1 || (offset > 0 && utc > local))
            return local;

        return utc;
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        if (!TryGetOffset(timeZone, out var offset) || offset == 0)
            return utc;

        var local = utc.AddHours(offset);
        if (local.Year > 9998 || (offset < 0 && local > utc))
            return utc;

        return local;
    }

    private bool TryGetOffset(string timeZone, out int offset)
    {
        offset = 0;
        if (string.IsNullOrEmpty(timeZone) || !_offsets.TryGetValue(timeZone, out offset))
            return false;

        return offset is >= -12 and <= 14;
    }
}
